var f=document.Application.NewFamilyDocument(@"C:\ProgramData\Autodesk\RVT 2027\Family Templates\English\Metric Structural Framing - Beams and Braces.rft");
try{return new{dims=new FilteredElementCollector(f).OfClass(typeof(Dimension)).Cast<Dimension>().Select(d=>new{id=d.Id.Value,refs=d.References.Cast<Reference>().Select(r=>new{id=r.ElementId.Value,stable=r.ConvertToStableRepresentation(f)}).ToArray()}).ToArray(),refs=new FilteredElementCollector(f).OfClass(typeof(ReferencePlane)).Cast<ReferencePlane>().Select(p=>new{id=p.Id.Value,name=p.Name,b=p.BubbleEnd.ToString(),f=p.FreeEnd.ToString()}).ToArray(),extrusions=new FilteredElementCollector(f).OfClass(typeof(Extrusion)).Cast<Extrusion>().Select(e=>new{id=e.Id.Value,start=e.StartOffset,end=e.EndOffset,profile=e.Sketch.Profile.Cast<CurveArray>().Select(a=>a.Cast<Curve>().Select(c=>new{a=c.GetEndPoint(0).ToString(),b=c.GetEndPoint(1).ToString()}).ToArray()).ToArray()}).ToArray(),views=new FilteredElementCollector(f).OfClass(typeof(View)).Cast<View>().Select(v=>new{id=v.Id.Value,name=v.Name,type=v.ViewType.ToString()}).ToArray()};}catch(Exception ex){return new{failure=ex.ToString()};}finally{f.Close(false);}


